/**
 * Explicit inventory of skill roots that are public in the catalog.
 *
 * Derived from `ai-tools.yaml` (repository root), the SSOT for which AI
 * coding tool has which plugins. Do not edit this file's SOURCE_REGISTRY
 * values by hand — add or remove plugins in ai-tools.yaml instead.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import yaml from "js-yaml";

const SCRIPT_DIRECTORY = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(SCRIPT_DIRECTORY, "..", "..");
const CONFIG_PATH = path.join(REPO_ROOT, "ai-tools.yaml");

// Display name shown in the catalog UI ("<tool> / <plugin>"). Mirrors
// DISPLAY_NAMES in tools/internal/plugin_meta/generate/generate_readme_tools_section.py.
const TOOL_DISPLAY_NAMES = {
  "claude-code": "Claude Code",
  cline: "Cline",
  codex: "Codex",
  copilot: "GitHub Copilot",
  cursor: "Cursor",
  antigravity: "Antigravity",
};

// Prefix used for this tool's registry ids. Usually the tool key itself,
// except "claude-code" which keeps the shorter historical "claude" prefix.
const ID_PREFIXES = {
  "claude-code": "claude",
  cline: "cline",
  codex: "codex",
  copilot: "copilot",
  cursor: "cursor",
  antigravity: "antigravity",
};

function loadConfig(configPath = CONFIG_PATH) {
  const data = yaml.load(fs.readFileSync(configPath, "utf8"));
  if (!data || typeof data !== "object" || !data.tools) {
    throw new Error(`${configPath} is missing a top-level 'tools' key`);
  }
  return data;
}

function pluginName(path_, kind) {
  const base = path_.split("/").pop();
  if (kind === "workspace") return "workspace";
  // ".claude" is the sole dot-prefixed "kind: plugin" entry; it is
  // registered in .claude-plugin/marketplace.json under the name "meta",
  // not its directory basename.
  if (base.startsWith(".")) return "meta";
  return base;
}

function registryId(idPrefix, path_, plugin) {
  if (path_.startsWith(".")) return `${idPrefix}-workspace`;
  if (plugin.startsWith(`${idPrefix}-`)) return plugin;
  return `${idPrefix}-${plugin}`;
}

function buildRegistry(config) {
  const registry = [];
  for (const [toolKey, tool] of Object.entries(config.tools)) {
    for (const entry of tool.plugins ?? []) {
      const plugin = pluginName(entry.path, entry.kind);
      const root = entry.skills_layout === "subdir" ? `${entry.path}/skills` : entry.path;
      registry.push({
        id: registryId(ID_PREFIXES[toolKey], entry.path, plugin),
        tool: TOOL_DISPLAY_NAMES[toolKey],
        plugin,
        root,
      });
    }
  }
  return registry;
}

export const SOURCE_REGISTRY = buildRegistry(loadConfig());
